<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot; use Throwable; use Pterodactyl\Services\Dezerx\Theme; class Art { private const MINECRAFT = [ 'paper' => 'paper', 'purpur' => 'paper', 'pufferfish' => 'paper', 'spigot' => 'paper', 'bukkit' => 'paper', 'folia' => 'paper', 'fabric' => 'fabric', 'quilt' => 'fabric', 'neoforge' => 'neoforge', 'forge' => 'forge', 'bungeecord' => 'bungeecord', 'waterfall' => 'bungeecord', 'velocity' => 'bungeecord', 'vanilla' => 'vanilla', 'sponge' => 'vanilla', 'minecraft' => 'vanilla', ]; private const GAMES = [ 'rust' => 'rust', 'palworld' => 'palworld', 'fivem' => 'fivem', 'redm' => 'redm', 'zomboid' => 'zomboid', 'hytale' => 'hytale', 'squad' => 'squad', 'arma' => 'arma3', ]; private static ?array $configured = null; public static function logo(?string $eggUuid, ?string $eggName): ?string { $row = self::configured($eggUuid); if (($row['logo'] ?? '') !== '') { return self::absolute($row['logo']); } $name = mb_strtolower((string) $eggName); foreach (self::MINECRAFT as $keyword => $slug) { if (str_contains($name, $keyword)) { return self::shipped("dezerx/eggs/{$slug}.webp"); } } foreach (self::GAMES as $keyword => $slug) { if (str_contains($name, $keyword)) { return self::shipped("dezerx/games/{$slug}.webp"); } } return self::shipped('dezerx/eggs/other.webp'); } public static function banner(?string $eggUuid, ?string $eggName): ?string { $row = self::configured($eggUuid); if (($row['image'] ?? '') !== '') { return self::absolute($row['image']); } $name = mb_strtolower((string) $eggName); foreach (self::MINECRAFT as $keyword => $slug) { if (str_contains($name, $keyword)) { return self::shipped("dezerx/eggs/bg/{$slug}.webp"); } } foreach (self::GAMES as $keyword => $slug) { if (str_contains($name, $keyword)) { return self::shipped("dezerx/games/{$slug}.webp"); } } return self::shipped('dezerx/eggs/bg/other.webp'); } public static function forDiscord(string $url): string { $base = BotConfig::panelUrl(); if (!str_starts_with($url, $base . '/')) { return $url; } $parts = parse_url(substr($url, strlen($base))); $path = ltrim((string) ($parts['path'] ?? ''), '/'); if (str_starts_with($path, 'api/') || preg_match('/\.(png|jpe?g|webp|gif)$/i', $path) !== 1) { return $url; } return BotConfig::panelUrl(route('dezerx.discordbot.media', ['path' => $path], false)) . (isset($parts['query']) ? '?' . $parts['query'] : ''); } public static function absolute(?string $url): ?string { $url = trim((string) $url); if ($url === '') { return null; } if (preg_match('#^https?://#i', $url) === 1) { return $url; } if (str_starts_with($url, 'data:')) { return null; } return BotConfig::panelUrl($url); } private static function shipped(string $path): ?string { return is_file(public_path($path)) ? BotConfig::panelUrl($path) : null; } private static function configured(?string $eggUuid): array { if ($eggUuid === null || $eggUuid === '') { return []; } if (self::$configured === null) { try { $rows = Theme::config()['servers.eggArt'] ?? []; } catch (Throwable) { $rows = []; } self::$configured = []; foreach (is_array($rows) ? $rows : [] as $row) { if (is_array($row) && is_string($row['egg'] ?? null)) { self::$configured[$row['egg']] = [ 'logo' => (string) ($row['logo'] ?? ''), 'image' => (string) ($row['image'] ?? ''), ]; } } } return self::$configured[$eggUuid] ?? []; } } 